 arrayfalsedatefmt_localtime
 IntlDateFormatterformatter
 stringstring
 intoffset&null;


 Convierte string en una fecha descompuesta (un &array;
 de campos), comenzando en offset y consumiendo tantos
 caracteres del string de entrada como sea posible.

  &reftitle.examples;

   Ejemplo con datefmt_localtime


<?php

$fmt = datefmt_create(
    'en_US',
    IntlDateFormatter::FULL,
    IntlDateFormatter::FULL,
    'America/Los_Angeles',
    IntlDateFormatter::GREGORIAN
);
$arr = datefmt_localtime($fmt, 'Wednesday, December 31, 1969 at 4:00:00 PM Pacific Standard Time', $offset);
echo 'Resultado del análisis ';
if ($arr) {
    foreach ($arr as $key => $value) {
        echo "$key : $value , ";
    }
}

?>




   Ejemplo orientado a objetos


<?php
$fmt = new IntlDateFormatter(
    'en_US',
    IntlDateFormatter::FULL,
    IntlDateFormatter::FULL,
    'America/Los_Angeles',
    IntlDateFormatter::GREGORIAN
);
$arr = $fmt->localtime('Wednesday, December 31, 1969 at 4:00:00 PM Pacific Standard Time', $offset);
echo 'Resultado del análisis ';
if ($arr) {
    foreach ($arr as $key => $value) {
        echo "$key : $value , ";
    }
}

?>



  &example.outputs;


